    for j in range(1, LOG):
        up_prev = up[j - 1]
        up_curr = up[j]
        for i in range(1, n + 1):
            up_curr[i] = up_prev[up_prev[i]]

    def get_kth_ancestor(node, k):
        for j in range(LOG):
            if (k >> j) & 1:
                node = up[j][node]
        return node

    # Euler Tour (tin, tout)
    tin = [0] * (n + 1)
    tout = [0] * (n + 1)
    timer = 0

    # Iterative DFS for Euler tour
    stack = [1]
    edge_idx = [0] * (n + 1)
    timer += 1
    tin[1] = timer

    while stack:
        u = stack[-1]
        if edge_idx[u] < len(adj[u]):
            v = adj[u][edge_idx[u]]
            edge_idx[u] += 1
            timer += 1
            tin[v] = timer
            stack.append(v)
        else:
            tout[u] = timer
            stack.pop()

