        if ql <= l and r <= qr:
            lazy[node] = val
            return
        mid = (l + r) // 2
        lz = lazy[node]
        if lz != 0:
            lazy[2 * node] = lz
            lazy[2 * node + 1] = lz
            lazy[node] = 0
        if ql <= mid:
            update(2 * node, l, mid, ql, qr, val)
        if qr > mid:
            update(2 * node + 1, mid + 1, r, ql, qr, val)

    def query(node, l, r, pos):
        if l == r:
            return lazy[node]
