        lz = lazy[node]
        if lz != 0:
            lazy[2 * node] = lz
            lazy[2 * node + 1] = lz
            lazy[node] = 0
        if pos <= mid:
            return query(2 * node, l, mid, pos)
        else:
            return query(2 * node + 1, mid + 1, r, pos)

    q = int(next(iterator))
    out = []

    for _ in range(q):
        op = next(iterator)
        if op == "1":
            v = int(next(iterator))
            k = int(next(iterator))
            top_v = query(1, 1, n, tin[v])
            if top_v == 0:
                ans = get_kth_ancestor(v, k)
