                    ans = top_v
                else:
                    ans = get_kth_ancestor(top_v, k - 1)
            out.append(str(ans))
        else:
            v = int(next(iterator))
            val = query(1, 1, n, tin[v])
            if val == 0:
                ql = tin[v] + 1
                qr = tout[v]
                if ql <= qr:
                    update(1, 1, n, ql, qr, v)

    sys.stdout.write("\n".join(out) + "\n")


